        return False
    if tuple(command[1:1 + len(family)]) != family or "--json" not in command:
        return False
    raw_project = option_value(command, "--project")
    if not raw_project:
        return False
    try:
        return Path(raw_project).expanduser().resolve() == project
    except OSError:
        return False

